import numpy as np
def sample_minp(logits, min_p=0.1, temperature=1.0, seed=0):
    rng = np.random.default_rng(seed)
    z = np.asarray(logits, float) / temperature
    e = np.exp(z - z.max()); p = e / e.sum()
    keep = p >= min_p * p.max()
    p = np.where(keep, p, 0.0); p /= p.sum()
    return int(rng.choice(len(z), p=p))
z = np.array([5., 4.5, 1., 0.5, 0.])
picks = {sample_minp(z, seed=s) for s in range(300)}
assert picks <= {0, 1, 2}
print('min-p OK:', sorted(picks))
